    [signer1, signer2, signer3, outsider] = await ethers.getSigners();
    const Multisig = await ethers.getContractFactory("MultisigController");
    multisig = await Multisig.deploy(
      [signer1.address, signer2.address, signer3.address],
      REQUIRED
    );
  })
